query ProjectHoursBenchmarkRaw(
  $projectId: ID!
  $startDate: Date!
  $endDate: Date!
  $page: Int!
  $pageSize: Int!
) {
  projectStaffCostList(
    page: $page
    pageSize: $pageSize
    orderBy: [{field: workDate, direction: ASC}, {field: id, direction: ASC}]
    filter: {
      projectId_Exact: $projectId
      workDate_Gte: $startDate
      workDate_Lte: $endDate
    }
  ) {
    pageInfo {
      totalCount
      pageSize
      currentPage
      totalPages
    }
    items {
      id
      workDate
      hours(targetUnit: "h") {
        value
        unit
      }
      projectStaffCostTask {
        id
        name
      }
      user {
        lastName
      }
    }
  }
}

